```JSON
{
  "kasaysayan_ng_prospect_park": {
    "pamagat": "Ang Kasaysayan ng Prospect Park, Brooklyn, NYC",
    "pangkalahatang_ideya": "Ang Prospect Park, na madalas ituring na obra maestra ng mga landscape architect na sina Frederick Law Olmsted at Calvert Vaux, ay isang malawak na pampublikong parke na may sukat na 585 ektarya (237 ha) sa puso ng Brooklyn, New York. Ang kasaysayan nito ay sumasalamin sa pag-unlad ng urban planning, landscape architecture, at pangangalaga sa komunidad.",
    "mga_pangunahing_arkitekto": [
      {
        "pangalan": "Frederick Law Olmsted at Calvert Vaux",
        "kontribusyon": "Sila ang parehong team na nagdisenyo ng Central Park sa Manhattan. Itinuring nila ang Prospect Park bilang kanilang pinakamahusay na gawa dahil sa mas malaking kalayaan sa pagdidisenyo at mas kaunting mga hadlang kumpara sa Central Park. Ang kanilang layunin ay lumikha ng isang rural na kanlungan (rural retreat) sa gitna ng lumalaking lungsod."
      }
    ],
    "timeline_ng_kasaysayan": [
      {
        "panahon": "Ang Ideya at Pagpaplano (1859-1865)",
        "deskripsyon": "Noong 1859, nagpasa ng batas ang New York State Legislature para maglaan ng lupa para sa isang malaking parke sa Lungsod ng Brooklyn (na noon ay hiwalay pa sa New York City). Ang tagumpay ng Central Park ay nagbigay-inspirasyon sa mga pinuno ng Brooklyn na lumikha ng sarili nilang malawak na pampublikong espasyo. Ang orihinal na plano ay naantala dahil sa Digmaang Sibil sa Amerika."
      },
      {
        "panahon": "Disenyo at Pagtatayo (1866-1873)",
        "deskripsyon": "Noong 1866, opisyal na kinomisyon sina Olmsted at Vaux para idisenyo ang parke. Agad nilang sinimulan ang konstruksyon. Sa panahong ito, nilikha ang mga pinakatanyag na bahagi ng parke, kabilang ang Long Meadow, ang Ravine, at ang Lake. Ang pangunahing bahagi ng konstruksyon ay natapos noong 1873, bagama't nagpatuloy pa ang mga pagpapabuti sa mga sumunod na dekada."
      },
      {
        "panahon": "Ang Ginintuang Panahon (Huling bahagi ng ika-19 na Siglo)",
        "deskripsyon": "Mabilis na naging tanyag ang parke sa mga residente ng Brooklyn. Ito ay naging sentro ng libangan at sosyal na aktibidad, mula sa pamamangka sa lawa, pagsakay sa kabayo, hanggang sa mga konsiyerto at piknik."
      },
      {
        "panahon": "Mga Pagbabago at Panahon ng Paghina (Ika-20 Siglo)",
        "deskripsyon": "Sa ilalim ng pamumuno ni Robert Moses bilang NYC Parks Commissioner, ilang pagbabago ang ginawa, tulad ng pagdaragdag ng mga palaruan, Wollman Rink, at ang Prospect Park Bandshell. Gayunpaman, pagsapit ng kalagitnaan ng ika-20 siglo, nagsimulang humina ang parke dahil sa pagbawas ng badyet ng lungsod at pagtaas ng krimen. Maraming bahagi nito ang napabayaan."
      },
      {
        "panahon": "Muling Pagkabuhay at Restorasyon (1987-Kasalukuyan)",
        "deskripsyon": "Noong 1987, itinatag ang Prospect Park Alliance, isang non-profit na organisasyon na nakikipagtulungan sa Lungsod ng New York para pangalagaan at ibalik sa dati ang parke. Sa pamamagitan ng public-private partnership na ito, nakalikom ng daan-daang milyong dolyar para sa malawakang restorasyon. Isinaayos ang mga makasaysayang istruktura tulad ng Boathouse at Carousel, at muling binuhay ang mga natural na lugar tulad ng Ravine. Ngayon, ang Prospect Park ay muling isang masigla at minamahal na bahagi ng komunidad."
      }
    ],
    "mga_natatanging_lugar_at_istruktura": [
      {
        "pangalan": "Grand Army Plaza",
        "paglalarawan": "Ang maringal na pasukan sa parke, na nagtatampok sa Soldiers' and Sailors' Arch, isang arko na alay sa mga beterano ng Digmaang Sibil."
      },
      {
        "pangalan": "Long Meadow",
        "paglalarawan": "Isang malawak na parang na may habang halos isang milya, na itinuturing na isa sa mga pinakamahusay na halimbawa ng pastoral landscape design sa Amerika."
      },
      {
        "pangalan": "The Ravine",
        "paglalarawan": "Isang masalimuot na gawang-taong kagubatan at daluyan ng tubig na ginaya sa Adirondack Mountains. Ito ang tanging natitirang kagubatan sa Brooklyn."
      },
      {
        "pangalan": "Prospect Park Lake",
        "paglalarawan": "Isang 60-ektaryang lawa na gawa ng tao, na sikat para sa pamamangka at pangingisda."
      },
      {
        "pangalan": "Boathouse",
        "paglalarawan": "Isang magandang istrukturang Beaux-Arts na itinayo noong 1905, na ngayon ay nagsisilbing Audubon Center."
      },
      {
        "pangalan": "Lefferts Historic House",
        "paglalarawan": "Isang makasaysayang bahay-bukid mula sa ika-18 siglo na inilipat sa parke noong 1918. Nag-aalok ito ng mga programa tungkol sa buhay sa Brooklyn noong unang panahon."
      }
    ],
    "kasalukuyang_katayuan": "Ang Prospect Park ay isang National Historic Landmark at nananatiling isa sa mga pinakamahalagang pampublikong espasyo sa New York City, na dinarayo ng milyun-milyong bisita bawat taon para sa libangan, palakasan, at pagpapahinga."
  }
}
```

